{
  "rules": [
    {
      "id": "rule_1",
      "description": "Ensure that the total debits and total credits are equal for each journal entry.",
      "gx_code": "gx.expect_column_values_to_be_equal_to_constant(column='total_debits', constant_value='total_credits')",
      "evidence_references": ["source_documentation"]
    },
    {
      "id": "rule_2",
      "description": "Ensure that the total debits and total credits are nonnegative integers.",
      "gx_code": "gx.expect_column_values_to_be_between(column='total_debits', min_value=0, max_value=None)",
      "evidence_references": ["source_documentation"]
    },
    {
      "id": "rule_3",
      "description": "Ensure that the currency is either USD or EUR.",
      "gx_code": "gx.expect_column_values_to_be_in_set(column='currency', value_set=['USD', 'EUR'])",
      "evidence_references": ["source_documentation"]
    },
    {
      "id": "rule_4",
      "description": "Ensure that the journal_id is unique across all entries.",
      "gx_code": "gx.expect_column_values_to_be_unique(column='journal_id')",
      "evidence_references": ["source_documentation"]
    }
  ],
  "abstentions": []
}
